from pathlib import Path
import re

path = Path('/home/ubuntu/pathfinder-ai/client/src/pages/Home.tsx')
text = path.read_text()
chat = '''function Chat({ chat, input, setInput, send, prompts, promptOpen, setPromptOpen, onNewChat }: { chat: { from: string; text: string }[]; input: string; setInput: (s: string) => void; send: (s?: string) => void; prompts: { id: number; category: string; promptText: string; displayOrder: number }[]; promptOpen: boolean; setPromptOpen: (open: boolean) => void; onNewChat: () => void }) { return <div className="mx-auto max-w-[850px]"><div className="mb-8 flex flex-col justify-between gap-5 sm:flex-row sm:items-end"><div><Pill color="teal"><Sparkles size={13} className="mr-1" /> Your career guide</Pill><h1 className="font-display mt-4 text-4xl tracking-[-.04em]">Let’s find a direction<br /><span className="text-[#0d9488]">that feels like you.</span></h1><p className="mt-3 text-[#6c8490]">One question at a time. No pressure to have the perfect answer.</p></div><div className="flex gap-2"><Button variant="outline" onClick={onNewChat}>+ New chat</Button><Button variant="outline" onClick={() => setPromptOpen(!promptOpen)}><Lightbulb size={16} /> Prompt library</Button></div></div>{promptOpen && <div className="mb-4 rounded-[22px] bg-[#e8f6f3] p-5"><div className="flex items-center justify-between"><p className="text-sm font-bold text-[#183b56]">Try a starter prompt</p><button onClick={() => setPromptOpen(false)} className="text-xs font-bold text-[#0f766e]">Close</button></div><div className="mt-4 grid gap-2 sm:grid-cols-2">{prompts.map(p => <button key={p.id} onClick={() => { setPromptOpen(false); send(p.promptText); }} className="rounded-xl bg-white p-3 text-left text-xs leading-5 text-[#52717d] transition hover:text-[#0f766e]"> <span className="mb-1 block text-[10px] font-bold uppercase tracking-[.12em] text-[#8aa0a8]">{p.category}</span>{p.promptText}</button>)}</div></div>}<div className="rounded-[26px] bg-white p-4 card-border sm:p-7"><div className="min-h-[360px] space-y-5">{chat.map((m, i) => <div key={i} className={`flex gap-3 ${m.from === "user" ? "justify-end" : ""}`}>{m.from === "ai" && <div className="mt-1 flex h-9 w-9 shrink-0 items-center justify-center rounded-full bg-[#dff7f1] text-[#0d9488]"><Sparkles size={16} /></div>}<div className={`max-w-[78%] rounded-[20px] px-4 py-3 text-sm leading-6 ${m.from === "ai" ? "rounded-tl-sm bg-[#f7fafc] text-[#52717d]" : "rounded-tr-sm bg-[#0d9488] text-white"}`}><Streamdown>{m.text}</Streamdown></div></div>)}</div><div className="mt-6 flex flex-wrap gap-2"><button onClick={() => send("Study")} className="rounded-full bg-[#e8f6f3] px-3 py-2 text-xs font-bold text-[#0f766e]">🎓 Study</button><button onClick={() => send("Work")} className="rounded-full bg-[#e7efff] px-3 py-2 text-xs font-bold text-[#2563eb]">💼 Work</button><button onClick={() => send("Skills")} className="rounded-full bg-[#fff6dc] px-3 py-2 text-xs font-bold text-[#a77408]">🛠 Skills</button><button onClick={() => send("I’m not sure yet")} className="rounded-full bg-[#edf4f5] px-3 py-2 text-xs font-bold text-[#52717d]">🧭 Explore</button></div><div className="mt-4 flex items-center gap-2 rounded-2xl border border-[#dce9ea] p-2 focus-within:border-[#0d9488]"><input value={input} onChange={e => setInput(e.target.value)} onKeyDown={e => e.key === "Enter" && send()} placeholder="Type whatever is on your mind..." className="min-w-0 flex-1 bg-transparent px-3 text-sm outline-none placeholder:text-[#9ab0b6]" /><button onClick={() => send()} className="flex h-10 w-10 items-center justify-center rounded-xl bg-[#0d9488] text-white"><ArrowRight size={18} /></button></div><p className="mt-4 text-center text-[11px] text-[#9ab0b6]">PathFinder offers guidance, not guarantees. Always verify requirements with the official source.</p></div></div> }'''
opp = '''function Opportunities({ filtered, query, setQuery, category, setCategory, province, setProvince, saved, toggleSave }: { filtered: any[]; query: string; setQuery: (s: string) => void; category: string; setCategory: (s: string) => void; province: string; setProvince: (s: string) => void; saved: number[]; toggleSave: (id: number) => void }) { return <div><div className="flex flex-col justify-between gap-5 sm:flex-row sm:items-end"><div><Pill color="blue">Opportunity hub</Pill><h1 className="font-display mt-4 text-4xl tracking-[-.04em]">Find something<br /><span className="text-[#0d9488]">worth moving towards.</span></h1><p className="mt-3 text-[#6c8490]">Curated opportunities with a real source to verify before you apply.</p></div><Pill color="green"><Bookmark size={13} className="mr-1" /> {saved.length} saved</Pill></div><div className="mt-8 flex flex-col gap-3 sm:flex-row"><div className="flex flex-1 items-center gap-3 rounded-2xl bg-white px-4 card-border"><Search size={18} className="text-[#8aa0a8]" /><input value={query} onChange={e => setQuery(e.target.value)} placeholder="Search opportunities, skills or organisations" className="h-12 flex-1 bg-transparent text-sm outline-none" /></div><select value={category} onChange={e => setCategory(e.target.value)} className="h-12 rounded-2xl border border-[#dce9ea] bg-white px-4 text-sm font-bold text-[#52717d] outline-none"><option>All</option><option>Study</option><option>Work</option><option>Skills</option><option>Business</option></select><select value={province} onChange={e => setProvince(e.target.value)} className="h-12 rounded-2xl border border-[#dce9ea] bg-white px-4 text-sm font-bold text-[#52717d] outline-none"><option>All</option><option>Gauteng</option><option>Western Cape</option><option>KwaZulu-Natal</option><option>Eastern Cape</option><option>National</option></select></div><p className="mt-4 text-xs text-[#8aa0a8]">Showing results from PathFinder’s curated list. Always verify requirements on the linked source.</p><div className="mt-5 grid gap-4 md:grid-cols-2">{filtered.map(o => <div key={o.id} className="group rounded-[22px] bg-white p-5 card-border transition hover:-translate-y-1 hover:shadow-xl hover:shadow-[#183b56]/[.06]"><div className="flex items-start justify-between gap-4"><Pill color={o.tone}>{o.category}</Pill><button onClick={() => toggleSave(o.id)} className={saved.includes(o.id) ? "text-[#0d9488]" : "text-[#b1c2c5] hover:text-[#0d9488]"} aria-label={`Save ${o.title}`}><Bookmark size={19} fill={saved.includes(o.id) ? "currentColor" : "none"} /></button></div><h3 className="mt-5 font-display text-2xl leading-tight">{o.title}</h3><p className="mt-1 text-sm font-bold text-[#52717d]">{o.org}</p><p className="mt-3 text-sm leading-6 text-[#6c8490]">{o.desc}</p><div className="mt-4 flex flex-wrap gap-2">{o.tags.map((t: string) => <span key={t} className="rounded-full bg-[#f7fafc] px-2.5 py-1 text-[11px] font-semibold text-[#6c8490]">{t}</span>)}</div><div className="mt-5 flex items-center justify-between border-t border-[#edf3f3] pt-4"><div className="flex items-center gap-1 text-xs font-semibold text-[#8aa0a8]"><MapPin size={13} /> {o.place}</div><div className="flex items-center gap-2"><span className="text-xs font-bold text-[#258044]">{o.score}% match</span><ChevronRight size={16} className="text-[#0d9488]" /></div></div><a href={o.sourceUrl || "#"} target="_blank" rel="noreferrer" className="mt-4 inline-flex items-center gap-2 text-sm font-bold text-[#0f766e]">Verify / Apply <ArrowRight size={15} /></a></div>)}</div>{filtered.length === 0 && <div className="rounded-[22px] bg-white p-10 text-center card-border"><Search className="mx-auto text-[#b1c2c5]" /><h3 className="mt-4 font-bold">No opportunities found</h3><p className="mt-2 text-sm text-[#6c8490]">Try a wider search or another category.</p></div>}</div> }'''
text = re.sub(r'function Chat\(.*?\nfunction Opportunities', chat + '\nfunction Opportunities', text, count=1, flags=re.S)
text = re.sub(r'function Opportunities\(.*?\nfunction Plan', opp + '\nfunction Plan', text, count=1, flags=re.S)
path.write_text(text)
